import {checkAccountLogin,escapeHTML as esc} from './engine.js?v=33';
import {canAccessExpansionDoc} from './expansion-engine.js?v=33';
import {archiveDocs} from './expansion-content.js?v=33';
import {caseDocs} from './campaign.js?v=33';
import {watchOriginalReading} from './original-reading.js?v=33';
import {createDwellCollector} from './auto-read.js?v=33';
import {RELAY_BV,CANTEEN_BV,VIDEOS,CARD_ROWS,RELAY_REGISTER,MAINTENANCE} from './network-content.js?v=33';
import {canViewVideo,canUsePortal,canUseShare,authorizeCard,queryCard,openCardOrder,recordVideoFrame,unlockShare,routeFromAddress} from './network-engine.js?v=33';
import {recordTable,tableCSV,downloadLocal} from './record-table.js?v=33';
import {videoScene} from './video-scene.js?v=33';

const clock=value=>`${String(Math.floor(value/60)).padStart(2,'0')}:${String(Math.floor(value%60)).padStart(2,'0')}`;
const cardTable=rows=>({title:'一卡通消费明细',columns:['交易流水号','交易时间','窗口 / 机号','商品摘要','金额（元）','凭条号'],rows});
const MENU={title:'夜宵窗口供应安排',columns:['日期','窗口02','窗口03','备注'],rows:[['周一','火鸡面 / 紫菜汤','车仔面','售完即止'],['周三','饭团 / 紫菜汤','车仔面','按到货调整'],['周四','火鸡面 / 饭团 / 紫菜汤','车仔面','21:40起供应'],['周五','火鸡面','车仔面','售完即止']]};
const portalNav=[['card','一卡通消费明细'],['menu','每周菜谱与采购公示'],['ledger','消杀台账公开栏'],['workorders','维修报备与归档'],['complaints','投诉建议箱']];
export function createNetwork({getState,save,view,collect,archive,toast,render,entered}){
 const current=()=>getState().network;
 const dwell=createDwellCollector();let player=null,playing=false,ticker=null,stamp=0,videoId=null,muted=true,audio=null,mediaState=null,playbackGeneration=0;
 const feedback=()=>'<p id="networkFeedback" class="network-feedback" role="status"></p>';
 function result(r){const node=view.querySelector('#networkFeedback');if(node){node.textContent=r.message||'';node.classList.toggle('success',r.ok);}if(!r.ok)toast(r.message);}
 function title(text,sub=''){return `<header class="network-page-title"><h1>${text}</h1>${sub?`<p>${sub}</p>`:''}</header>`;}
 function locked(message){view.innerHTML=`<section class="network-locked">${title('这份页面还没有同步',message)}<a href="#directory">回调查目录</a></section>`;}
 function portalFrame(page,body){view.innerHTML=`<section class="portal-site"><div class="portal-utility"><span>青禾高级中学 · 校内服务</span><span>办事指南　|　服务电话 8062</span></div><header class="portal-masthead"><a href="#portal/home" class="portal-brand"><b>禾</b><span>智慧后勤服务大厅<small>QINGHE CAMPUS SERVICES</small></span></a><span class="portal-year">服务师生 · 信息公开</span></header><div class="portal-notice"><b>通知</b><span>一卡通消费记录按自然日查询，撤销交易保留审计记录。历史公示请切换“含归档”。</span></div><div class="portal-layout"><aside class="portal-sidebar"><h2>服务导航</h2><a href="#portal/home" ${page==='home'?'aria-current="page"':''}>服务首页</a>${portalNav.map(([id,text])=>`<a href="#portal/${id}" ${page===id?'aria-current="page"':''}>${text}</a>`).join('')}${getState().caseSolved&&getState().expansion.stage>=1?`<a href="#portal/timeline" ${page==='timeline'?'aria-current="page"':''}>核查阅览工作台</a>`:''}<small>学生查询与核查阅览<br>按各自授权范围开放</small></aside><div class="portal-main"><div class="portal-crumb">服务大厅 / ${esc(portalNav.find(([id])=>id===page)?.[1]||(page==='timeline'?'核查阅览工作台':'校园后勤'))}</div>${body}</div></div><footer class="portal-footer">青禾高级中学后勤服务中心 · 信息公开存档<br>建议使用分辨率 1280×720 以上浏览</footer></section>`;}
 function tableBlock(id,d,{collectable=false}={}){const s=getState(),held=s.expansion.evidence.includes(id);return `<section class="portal-record-block"><header><h2>${esc(d.title)}</h2><button type="button" data-record-download="${id}">下载CSV</button></header>${recordTable(d,{key:id,interactive:true,selected:current().tableMarks[id]||[]})}${collectable?`<button type="button" class="portal-button" data-archive-collect="${id}">${held?'✓ 已保存副本':'保存这份核查副本'}</button>`:''}</section>`;}
 function portal(page='home'){
  if(!['home',...portalNav.map(x=>x[0]),'order','timeline'].includes(page))return locked('没有找到这项后勤服务。');
  if(!canUsePortal(getState(),page)){portalFrame(page,title('查询范围尚未开放','等调查中的授权材料交到你手里，再查看这一项。')+'<a href="#directory">查看当前调查</a>');return;}
  if(page==='home')return portalFrame(page,`<div class="portal-banner"><small>青禾校园网 · 后勤事务</small><h1>后勤服务，一站办理</h1><p>消费记录 · 菜谱公示 · 设备报备</p><span class="portal-building" aria-hidden="true">▤ ▤ ▤</span></div><div class="portal-home-grid"><section><h2>常用服务</h2><a href="#portal/card">一卡通交易查询 <span>进入办理 →</span></a><a href="#portal/menu">本周食堂菜谱 <span>查看公示 →</span></a><a href="#portal/workorders">历史维修记录 <span>档案查询 →</span></a></section><section><h2>通知公告</h2><p>03-24　夜宵取餐凭条请妥善保管</p><p>03-20　意见箱离线维护说明</p><p>03-17　设备公示支持按工单号检索</p></section></div>`);
  if(page==='card')return cardPage();if(page==='order')return orderPage();if(page==='timeline')return timelinePage();
  if(page==='ledger')return ledgerPage();if(page==='workorders')return workordersPage();
  if(page==='menu')return portalFrame(page,title('每周菜谱与采购公示','2025年3月10日—3月16日 · 食堂夜宵窗口')+tableBlock('menu',MENU)+`<section class="portal-disclosure"><h2>采购公示摘要</h2><p>主食按当日验收批次入库；餐具周转与消杀服务另行登记。原始凭证不在菜谱栏公开。</p>${getState().caseSolved&&getState().expansion.stage>=5?'<a href="#archive/contract">查阅获准的合同核查副本 →</a>':''}</section>`);
  portalFrame(page,title('投诉建议箱','维护期间可查看既有公示，建议先存为草稿。')+`<article class="portal-disclosure"><h2>已回复的意见</h2><p>“夜宵窗口关得太早”　03-17</p><p>回复：售完会提前清台，供应时段以当日公告为准。</p><p>“设备报备找不到了”　03-18</p><p>回复：完结工单进入历史归档，查编号时请一并勾选归档记录。</p></article><form id="complaintDraft"><label>建议内容<textarea name="message" rows="5" maxlength="1000" required>${esc(current().complaintDraft||'')}</textarea></label><button class="portal-button">保存建议草稿</button><p class="portal-help">当前为离线存档，草稿不会发送至学校。</p></form>${feedback()}`);
 }
 function cardPage(){const s=current();let body=title('一卡通消费明细','仅显示持卡人授权查询的交易记录。')+`<details class="portal-local-note"><summary>杰哥交给你的查询便笺（本机留存）</summary><p>“学号20220327。和资料柜用同一条授权口令，规则在存根背面。只查那几天，别翻我别的账。”</p>${caseDocs.pickup.body}</details>`;
  if(!s.cardAuthorized){portalFrame('card',body+`<form id="cardLogin" class="portal-form"><h2>学生查询登录</h2><label>学号<input name="student" inputmode="numeric" autocomplete="off" required></label><label>授权查询口令<input name="password" type="password" autocomplete="off" required></label><button class="portal-button">进入查询</button>${feedback()}</form>`);return;}
  body+=`<div class="portal-session">当前查询：20220327 · 杰哥授权记录<button type="button" data-card-logout>退出查询</button></div><form id="cardQuery" class="portal-query"><label>开始日期<input type="date" name="from" value="${esc(s.cardQuery?.from||'2025-03-12')}" required></label><label>结束日期<input type="date" name="to" value="${esc(s.cardQuery?.to||'2025-03-14')}" required></label><button class="portal-button">查询交易</button></form>${feedback()}`;
  if(s.cardQuery){const rows=CARD_ROWS.filter(r=>r[1].slice(0,10)>=s.cardQuery.from&&r[1].slice(0,10)<=s.cardQuery.to);body+=tableBlock('card',cardTable(rows));body+=rows.length?`<div class="portal-order-links">${rows.map(r=>`<button type="button" data-card-order="${r[0]}">${r[1].slice(5,16)} · 查看凭条 ${r[5]}</button>`).join('')}</div>`:'<p class="portal-empty">此范围内没有交易，修改日期后可再次查询。</p>';}
  portalFrame('card',body);
 }
 function orderPage(){const state=getState();if(!current().orderOpen&&!state.savedDocs.includes('receipt'))return portalFrame('card',title('请先查询对应交易','需要在消费明细里选中相应的凭条，才能显示商品项。')+'<a class="portal-button" href="#portal/card">返回消费查询</a>');
  portalFrame('order',title('交易凭条 · 0313-0367','2025-03-13 21:47:12 / QH-C02 / 夜宵窗口02')+`<div class="portal-receipt"><div><span class="receipt-state">交易成功</span><h2>￥18.00</h2><p>流水 C0313-2147</p><table><tr><th>火鸡面 × 1</th><td>12.00</td></tr><tr><th>饭团 × 1</th><td>4.00</td></tr><tr><th>紫菜汤 × 1</th><td>2.00</td></tr></table><p>取餐号 0367　｜　机号 QH-C02</p><button class="portal-button" type="button" data-save-receipt>保存交易凭条</button><p data-network-reading role="status">阅读片刻后自动收入调查本。</p></div><img src="assets/meal-receipt.svg" alt="夜宵凭条复印留存，火鸡面、饭团和紫菜汤分开计价"></div><div class="portal-return"><a href="#portal/card">返回查询</a><a href="#accounts/jie">打开杰哥资料柜取桌面照片 →</a><a href="#chapter/4">返回第4章核对 →</a></div>`);
  watchCurrentRead(()=>rememberReceipt(),()=>!!current().orderOpen||getState().savedDocs.includes('receipt'));
 }
 function rememberReceipt(){if(!current().orderOpen&&!getState().savedDocs.includes('receipt'))return;const s=getState();if(!s.savedDocs.includes('receipt'))s.savedDocs.push('receipt');if(!s.read.includes('casefile:receipt'))s.read.push('casefile:receipt');collect('receipt',true);save();const node=view.querySelector('[data-network-reading]');if(node)node.textContent='✓ 已收入调查本';}
 function watchCurrentRead(remember,allowed){const state=getState(),hash=location.hash,status=view.querySelector('[data-network-reading]');if(!status)return;watchOriginalReading({collector:dwell,state,getState,hash,getHash:()=>location.hash,entered,computer:document.querySelector('#computer'),appWindow:document.querySelector('#appWindow'),reader:null,document,status,collect:remember,stillAllowed:allowed});}
 function timelinePage(){if(!canAccessExpansionDoc(getState(),'swipe'))return portalFrame('timeline',title('核查阅览需要登录','尚未保存的私有流水需要授权登录；已有副本及公开记录仍可重读。')+'<a class="portal-button" href="#staff-login">登录授权阅览号</a>'+['roster','attendance','signoff'].filter(id=>canAccessExpansionDoc(getState(),id)).map(id=>tableBlock(id,archiveDocs[id],{collectable:true})).join(''));
  const ids=['roster','swipe','attendance','signoff'];portalFrame('timeline',title('到场记录核查工作台','导出范围：2025-03-12—2025-03-14 / 原始编号保留')+`<p class="portal-help">按卡号前缀、日期、交易状态及名册核对。点击某行可选中，下载保留全部原始行。</p><div class="portal-source-actions">${ids.map(id=>`<div><strong>${esc(archiveDocs[id].title)}</strong><button type="button" data-archive-collect="${id}">${getState().expansion.evidence.includes(id)?'✓ 已保存':'保存副本'}</button><button type="button" data-record-download="${id}">下载CSV</button></div>`).join('')}</div>${archive.timelineMarkup()}<p id="archiveFeedback" class="archive-feedback" role="status"></p><p data-archive-revelation></p><section id="archiveAfter" ${getState().expansion.stage>=2?'':'hidden'}><p>这一组材料已经核对，签收和点名不能支持“整晚都在教室”。</p><a class="portal-button" href="#annex/15">返回调查，继续第15章 →</a></section>`);
 }
 function ledgerPage(){const s=getState().expansion;portalFrame('ledger',title('消杀台账公开栏','L-0313 / 原导出包需先解密，明细不使用网页占位数据。')+`<div class="portal-file-strip"><span>▤</span><div><strong>L-0313_消杀台账.xlsx.enc</strong><small>关联消毒柜 XD-02 · 工作副本</small></div><a href="#pan/ledger">网盘文件页 →</a></div>${!s.vault?`<div class="portal-error"><strong>预览失败：需要导出包口令</strong><p>ERR_PREVIEW_NO_KEY · 刷新不会解开此文件。</p></div><p><a href="#archive/blackboard">查看黑板报原照片与导出说明 →</a></p><form id="archiveVault" class="portal-query"><label>附件口令<input name="password" type="password" inputmode="numeric" maxlength="12" required></label><button class="portal-button">验证并解密附件</button></form>`:''}<p id="archiveFeedback" class="archive-feedback" role="status"></p><p data-archive-revelation></p>${s.workbook?tableBlock('ledger',{...s.workbook,title:'L-0313 消杀台账'},{collectable:true}):s.vault?'<p>验证已通过，但预览副本未完整保留，请重新载入原加密附件。</p><form id="archiveVault" class="portal-query"><label>附件口令<input name="password" type="password" required></label><button class="portal-button">重新载入</button></form>':''}<div id="archiveAfter" ${s.vault?'':'hidden'}><div class="portal-source-actions"><button type="button" data-archive-download ${s.workbook?'':'disabled'}>下载原Excel</button><a href="#portal/workorders">核对维修报备归档 →</a><a href="#annex/18">带回第18章调查 →</a></div></div>`);}
 function workordersPage(){const search=current().maintenanceSearch||{query:'',archived:false},q=search.query.toLowerCase(),found=search.archived&&/消毒|消杀|餐具|回路|维修|wx0313|xd-02/.test(q);portalFrame('workorders',title('维修报备与归档','办结记录移入历史库，默认不列入在办工单。')+`<form id="maintenanceSearch" class="portal-query"><label>关键词 / 工单号<input name="query" value="${esc(search.query)}" placeholder="设备名称、报修内容或编号" maxlength="80"></label><label class="portal-check"><input type="checkbox" name="archived" ${search.archived?'checked':''}> 含归档记录</label><button class="portal-button">检索</button></form><article class="portal-current-order"><h2>在办工单</h2><p>WX0403-02　水房水龙头漏水　待领料</p><p>WX0403-06　二楼灯管更换　已派单</p></article>${found?tableBlock('outage',MAINTENANCE,{collectable:canAccessExpansionDoc(getState(),'outage')})+`<p class="portal-help">原工单反映设备停用时段，不能据此判断个人感染来源。请与同设备、同日台账核对。</p><p>附记：广播站存有当晚走廊影像，镜像编号 <code>${CANTEEN_BV}</code>。走廊照明不是该专用回路。</p><a href="#portal/ledger">回看该日消杀台账 →</a>`:search.query?'<p class="portal-empty">当前筛选没有命中对应工单。已办结的报备可连同历史归档一起查。</p>':'<p class="portal-help">输入设备名称或工单号检索；不提供全部历史档案的展开目录。</p>'}`);}
 function videoFrame(body){view.innerHTML=`<section class="video-site"><header class="video-top"><a href="#video" class="video-brand">▣ <strong>哔哩哔哩</strong><small>校园搬运镜像</small></a><nav><a href="#video">首页</a><a href="#dynamic/radio">动态</a><a href="#video">校园</a></nav><form id="mirrorSearch"><input name="query" aria-label="镜像站内搜索" placeholder="搜索视频、UP主或BV号" autocomplete="off" required><button aria-label="搜索">⌕</button></form><span class="video-user">游客</span></header>${body}<footer class="video-footer">青禾校园影像存档 · 评论和弹幕保留上传时的语境<br>弹幕及评论保留原上传时的语境，画面存档由社团整理。</footer></section>`;}
 function videoHome(query=''){const normalized=query.trim().toLowerCase();const hits=Object.values(VIDEOS).filter(v=>canViewVideo(getState(),v.id)&&(normalized?[v.id,v.title,v.up].some(text=>text.toLowerCase().includes(normalized)):v.kind==='daily'));videoFrame(title(query?'视频搜索：'+esc(query):'校园分区','老链接里的BV号也可以直接填进地址栏。')+`<div class="mirror-results">${hits.map(v=>`<a class="mirror-result" href="#video/${v.id}"><div class="mirror-thumb">${videoScene(v.kind,0)}<span>${clock(v.duration)}</span></div><h2>${esc(v.title)}</h2><p>${v.up} · ${v.views}播放</p></a>`).join('')||'<p class="portal-empty">没有找到这段缓存。试试帖子里记下的BV号或标题。</p>'}</div>`);}
 function videoPage(id){if(!Object.hasOwn(VIDEOS,id)||!canViewVideo(getState(),id))return videoFrame(title('视频暂未同步','请核对编号，或在拿到对应资料后再访问。')+'<a href="#video">返回镜像检索</a>');const v=VIDEOS[id],t=current().videoTimes[id]||0;videoId=id;mediaState=getState();player={time:t,kind:v.kind,duration:v.duration};playing=false;muted=true;
  videoFrame(`<div class="video-watch"><article><h1>${esc(v.title)}</h1><p class="video-meta">${v.views}播放　${v.danmaku.length}条弹幕　${v.date}　${v.id}</p><section class="mirror-player" data-playing="false"><div class="player-screen" id="playerScreen">${videoScene(v.kind,t)}<div class="danmaku-layer" id="danmakuLayer" aria-hidden="true"></div><div class="player-subtitle" id="playerSubtitle"></div><span class="player-watermark">青禾 · 存档画面</span></div><div class="player-controls"><button type="button" data-video-play aria-label="播放视频">▶</button><button type="button" data-video-skip="-5" aria-label="后退五秒">−5s</button><input type="range" id="videoSeek" min="0" max="${v.duration}" step="1" value="${t}" aria-label="视频播放进度"><button type="button" data-video-skip="5" aria-label="前进五秒">+5s</button><span id="videoClock">${clock(t)} / ${clock(v.duration)}</span><button type="button" data-video-mute aria-pressed="true">静音</button></div></section><div class="video-actions"><button type="button" data-video-like>♡ 点赞</button><button type="button" data-video-capture>▣ 记录当前画面</button><button type="button" data-video-frame-download>下载当前帧</button></div>${feedback()}<article class="video-description"><p>${esc(v.description)}</p><small>画外音有同步文字轨；可暂停、拖动进度或用方向键逐秒定位。</small></article><section class="mirror-comments"><h2>评论 <small>按热度排序</small></h2>${v.kind==='relay'?`<article class="mirror-comment pinned"><b>置顶 · 青禾摄影社</b><p>高清素材放这：<a href="#pan/relay">pan.qinghe.local/s/relay</a>。提取顺序看简介，日期用拍摄的那天，别用上传日。我没把领图单扫进来，那张找自己的照片袋。</p></article><article class="mirror-comment"><b>一放学就饿</b><p>1分20秒以后相机是不是歪了？后面那个场记板比跑道都清楚。</p><small>27人觉得有用　回复 3</small></article><article class="mirror-comment"><b>宋然</b><p>我只是去还三脚架，不是在器材室关了一下午。远处连脸都看不清，别给我编请假记录。</p><small>摄影社回复：原卷和器材交接页都留着，剪辑日期不是拍摄日期。</small></article>`:'<article class="mirror-comment pinned"><b>置顶 · 青禾广播站</b><p>只拍到走廊，设备状态请对照后勤正式工单。不要拿亮着的灯证明消毒机在运行。</p></article>'}</section></article><aside class="video-up"><div class="up-profile"><span class="up-avatar">${v.kind==='relay'?'摄':'播'}</span><div><h2>${v.up}</h2><p>青禾高中学生社团</p></div></div><button type="button" data-video-follow>＋ 关注</button><h3>镜像信息</h3><p>上传日期 ${v.date}</p><p>分P：本地缓存 / ${clock(v.duration)}</p><a href="#dynamic/radio">查看广播站动态 →</a><details><summary>播放操作</summary><p>进度条可直接拖动。记录时会保留画面时刻，弹幕另作参考。</p></details></aside></div>`);updatePlayer(false);
 }
 function updatePlayer(rebuild=true){if(!player||!videoId)return;const t=player.time,v=VIDEOS[videoId],screen=view.querySelector('#playerScreen');if(!screen)return;if(rebuild){const old=screen.querySelector('svg');if(old)old.outerHTML=videoScene(v.kind,t);}const detail=screen.querySelector('[data-scene-detail]');if(detail){detail.removeAttribute('hidden');detail.style.display=t>=82&&t<=88?'':'none';}
  const dm=v.danmaku.filter(d=>t>=d.at&&t<d.at+6);view.querySelector('#danmakuLayer').innerHTML=dm.map((d,i)=>`<span style="top:${18+i*24}%;transform:translateX(${Math.max(-40,80-(t-d.at)*22)}%)">${esc(d.text)}</span>`).join('');
  view.querySelector('#playerSubtitle').textContent=t<12?(v.kind==='relay'?'2024年10月18日 · 校运会正式比赛':v.description):t>=82&&t<=88?(v.kind==='relay'?'场外声：B机先别收，三脚架还在那边。':'场外声：后门先别走，那块维修牌还挂着。'):'';
  view.querySelector('#videoSeek').value=t;view.querySelector('#videoClock').textContent=`${clock(t)} / ${clock(v.duration)}`;view.querySelector('.mirror-player').dataset.playing=String(playing);const button=view.querySelector('[data-video-play]');button.textContent=playing?'❚❚':'▶';button.setAttribute('aria-label',playing?'暂停视频':'播放视频');
 }
 function persistTime(){if(player&&videoId&&mediaState===getState()){current().videoTimes[videoId]=player.time;save();}}
 function stopPlayback(){playbackGeneration++;playing=false;clearInterval(ticker);ticker=null;persistTime();if(audio){audio.close().catch(()=>{});audio=null;}if(window.speechSynthesis?.speaking)window.speechSynthesis.cancel();}
 function suspend(){dwell.cancel();stopPlayback();player=null;videoId=null;mediaState=null;}
 function play(){if(!player)return;if(playing){stopPlayback();updatePlayer(false);return;}if(player.time>=player.duration)player.time=0;playing=true;const generation=++playbackGeneration;stamp=performance.now();updatePlayer(false);ticker=setInterval(()=>{if(generation!==playbackGeneration)return;if(!player||mediaState!==getState()||(document.visibilityState!=='visible'||document.querySelector('dialog[open]')||document.querySelector('#appWindow')?.hidden)){stopPlayback();updatePlayer(false);return;}const now=performance.now(),before=player.time;player.time=Math.min(player.duration,player.time+(now-stamp)/1000);stamp=now;if(Math.floor(before)<84&&player.time>=84&&!muted)cueSound(true);updatePlayer(false);if(player.time>=player.duration){stopPlayback();updatePlayer(false);}},150);}
 function seek(value){if(!player)return;player.time=Math.max(0,Math.min(player.duration,Number(value)||0));stamp=performance.now();persistTime();updatePlayer();}
 function cueSound(speak=false){try{const Context=window.AudioContext||window.webkitAudioContext;if(!Context)return;audio=audio||new Context();audio.resume().catch(()=>{});const tone=audio.createOscillator(),gain=audio.createGain();tone.frequency.value=880;gain.gain.setValueAtTime(.025,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.12);tone.connect(gain);gain.connect(audio.destination);tone.start();tone.stop(audio.currentTime+.13);const voice=window.speechSynthesis?.getVoices().find(v=>v.localService&&/^zh/.test(v.lang));if(speak&&voice&&typeof SpeechSynthesisUtterance!=='undefined'){const words=new SpeechSynthesisUtterance(VIDEOS[videoId]?.kind==='relay'?'B机先别收，三脚架还在那边。':'后门先别走，那块维修牌还挂着。');words.voice=voice;words.lang='zh-CN';words.volume=.45;window.speechSynthesis.speak(words);}}catch{}}
 function dynamic(){videoFrame(title('青禾广播站的动态','2024年秋—2025年春 · 留存')+`<div class="mirror-dynamics"><article><b>青禾广播站</b><small>2024-10-20</small><p>摄影社接力花絮已经搬过去了。找不到领图登记的，看置顶源素材，不是所有照片都在同一天拍的。</p><code>${RELAY_BV}</code></article><article><b>青禾广播站</b><small>2025-03-18</small><p>食堂设备相关反馈请找后勤报备栏。视频里亮着的走廊灯，不是消毒柜电源。</p></article></div>`);}
 function panFrame(body){view.innerHTML=`<section class="pan-site"><header class="pan-header"><a href="#pan"><b>▰</b> 青禾网盘</a><span>校内资料交换</span><small>访客 / 公开分享</small></header><div class="pan-layout"><aside><a href="#pan" aria-current="page">▤ 公开分享</a><a href="#pan">◷ 最近提取</a><p>文件由上传者分享，过期目录请向原作者询问。</p></aside><div class="pan-main">${body}</div></div><footer>青禾网络信息中心 · 只读存档</footer></section>`;}
 function pan(id){if(!id)return panFrame(title('公开资料夹','请输入分享链接或从上传者给出的链接进入。')+`<form id="panLocate" class="pan-locate"><input name="share" aria-label="分享链接" placeholder="pan.qinghe.local/s/…" required><button>打开分享</button></form><h2>最近提取</h2>${current().panUnlocked.includes('relay')?'<a class="pan-recent" href="#pan/relay">▰ 摄影社运动会原素材</a>':'<p class="pan-empty">还没有提取记录。</p>'}`);
  if(!canUseShare(getState(),id))return panFrame(title('分享未同步','核对链接，或在调查拿到这份目录后再来。'));
  if(id==='blackboard')return panFrame(title(archiveDocs.blackboard.title,'广播站公开相册 / 2024年9月')+`<figure class="pan-frame-preview"><img class="pan-blackboard" src="${archiveDocs.blackboard.image}" alt="黑板报留有开学与夜宵试运行两组日期"></figure><article class="pan-source-note">${archiveDocs.blackboard.body}</article><button type="button" class="pan-button" data-archive-collect="blackboard">${getState().expansion.evidence.includes('blackboard')?'✓ 已保存副本':'保存黑板报副本'}</button><a class="pan-return" href="#portal/ledger">返回后勤台账验证附件 →</a>`);
  if(id==='ledger')return panFrame(title('L-0313_消杀台账.xlsx.enc','分享者：后勤核查工作副本')+`<article class="pan-protected"><span>▤</span><h2>文件已加密</h2><p>网盘仅保留原文件。请通过后勤门户校验口令、预览工作表并下载原Excel。</p><a href="#portal/ledger">到后勤台账页验证 →</a></article>`);
  if(!current().panUnlocked.includes(id))return panFrame(title('摄影社 · 运动会源素材','分享者：青禾摄影社 / 2024-10-20')+`<form id="panExtract" class="pan-extract"><span class="pan-lock">▰</span><h2>请输入提取码</h2><label>提取码<input name="password" type="password" maxlength="16" autocomplete="off" required></label><p>提取顺序由上传者写在视频简介中。</p><button>提取文件</button>${feedback()}</form>`);
  panFrame(title('运动会源素材 / 原始交接','只读目录 · 修改时间2024-10-20')+`<div class="pan-files"><div><span>▧</span><strong>relay_0124_原帧.svg</strong><small>正式比赛 / 高清场记帧</small><button type="button" data-relay-frame-download>下载</button></div><div><span>▤</span><strong>源素材交接登记.csv</strong><small>拍摄日期与机位</small><button type="button" data-record-download="relay">下载</button></div><div><span>▤</span><strong>器材借还说明.txt</strong><small>附注：离开器材室不代表整场缺席；弹幕姓名未经确认。</small></div></div><figure class="pan-frame-preview">${videoScene('relay',84)}<figcaption>原帧标记：2024-10-18 / 14:06:24。文件时间与视频上传时间分开记录。</figcaption></figure>${tableBlock('relay',RELAY_REGISTER)}<button type="button" class="pan-button" data-save-relay>保存拍摄登记</button><p data-network-reading role="status">阅读片刻后自动记入调查本。</p><a class="pan-return" href="#casefile/sports-slip">返回照片领取单核对机位与日期 →</a>`);
  watchCurrentRead(()=>collect('relayRegister',true),()=>current().panUnlocked.includes('relay'));
 }
 function downloadable(key){const s=getState();if(key==='card'&&current().cardAuthorized&&current().cardQuery)return cardTable(CARD_ROWS.filter(r=>r[1].slice(0,10)>=current().cardQuery.from&&r[1].slice(0,10)<=current().cardQuery.to));if(key==='relay'&&current().panUnlocked.includes('relay'))return RELAY_REGISTER;if(key==='menu')return MENU;if(key==='ledger'&&s.expansion.vault&&s.expansion.workbook)return {...s.expansion.workbook,title:'L-0313'};if(key==='outage'&&canUsePortal(s,'workorders'))return MAINTENANCE;if(['roster','swipe','attendance','signoff'].includes(key)&&canAccessExpansionDoc(s,key))return archiveDocs[key];return null;}
 function markRow(row){const table=row.closest('[data-record-table]'),key=table.dataset.recordTable,id=row.dataset.recordRow,radio=row.querySelector('input[type=radio]');if(radio){radio.checked=true;current().tableMarks[key]=[id];}else{const previous=current().tableMarks[key]||[];current().tableMarks[key]=previous.includes(id)?previous.filter(v=>v!==id):[...previous,id];}table.querySelectorAll('[data-record-row]').forEach(r=>{const active=current().tableMarks[key].includes(r.dataset.recordRow);r.classList.toggle('record-selected',active);const button=r.querySelector('[data-row-toggle]');if(button){button.setAttribute('aria-pressed',String(active));button.textContent=active?'已标记':'标记';}});save();}
 document.addEventListener('click',e=>{const b=e.target.closest('button,a'),row=e.target.closest('[data-record-row]');if(row&&view.contains(row)&&(row.querySelector('input[type=radio]')||row.querySelector('[data-row-toggle]')))markRow(row);if(!b)return;
  if(b.hasAttribute('data-card-logout')){Object.assign(current(),{cardAuthorized:false,cardQuery:null,orderOpen:false});save();cardPage();return;}
  if(b.dataset.cardOrder){if(openCardOrder(getState(),b.dataset.cardOrder)){save();location.hash='#portal/order';}else toast('这张日常交易的商品明细未包含在本次授权中。');return;}
  if(b.hasAttribute('data-save-receipt')){rememberReceipt();return;}
  if(b.dataset.recordDownload){const d=downloadable(b.dataset.recordDownload);if(d)downloadLocal(tableCSV(d),b.dataset.recordDownload+'_原始记录.csv');else toast('这份明细还没有载入当前授权范围。');return;}
  if(b.hasAttribute('data-video-play')){play();return;}if(b.dataset.videoSkip){seek((player?.time||0)+Number(b.dataset.videoSkip));return;}
  if(b.hasAttribute('data-video-mute')){muted=!muted;b.textContent=muted?'静音':'音效开';b.setAttribute('aria-pressed',String(muted));if(muted){if(audio){audio.close().catch(()=>{});audio=null;}if(window.speechSynthesis?.speaking)window.speechSynthesis.cancel();}else if(playing)cueSound(player?.time>=82&&player?.time<=88);return;}
  if(b.hasAttribute('data-video-capture')){if(!player)return;const r=recordVideoFrame(getState(),videoId,player.time);if(r.ok){if(r.clue)collect(r.clue);persistTime();save();}result(r);return;}
  if(b.hasAttribute('data-video-frame-download')){if(player)downloadLocal(videoScene(player.kind,player.time),'青禾影像_'+clock(player.time).replace(':','')+'.svg','image/svg+xml');return;}
  if(b.hasAttribute('data-relay-frame-download')){if(current().panUnlocked.includes('relay'))downloadLocal(videoScene('relay',84),'relay_0124_原帧.svg','image/svg+xml');return;}
  if(b.hasAttribute('data-save-relay')){if(current().panUnlocked.includes('relay'))collect('relayRegister');return;}
  if(b.hasAttribute('data-video-like')){b.textContent=b.textContent.includes('已赞')?'♡ 点赞':'♥ 已赞';return;}if(b.hasAttribute('data-video-follow'))b.textContent=b.textContent.includes('已关注')?'＋ 关注':'✓ 已关注';
 });
 document.addEventListener('change',e=>{if(e.target.matches('[data-record-table] input[type=radio]'))markRow(e.target.closest('[data-record-row]'));});
 document.addEventListener('input',e=>{if(e.target.id==='videoSeek')seek(e.target.value);});
 document.addEventListener('submit',e=>{const form=e.target;if(!['cardLogin','cardQuery','maintenanceSearch','mirrorSearch','panExtract','panLocate','complaintDraft'].includes(form.id))return;e.preventDefault();const data=new FormData(form);
  if(form.id==='cardLogin'){const r=authorizeCard(getState(),data.get('student'),data.get('password'),checkAccountLogin);if(r.ok){save();cardPage();}result(r);}
  if(form.id==='cardQuery'){const r=queryCard(getState(),data.get('from'),data.get('to'));if(r.ok){save();cardPage();result({ok:true,message:`查询完成，共${r.rows.length}笔交易。`});}else result(r);}
  if(form.id==='maintenanceSearch'){current().maintenanceSearch={query:String(data.get('query')||'').slice(0,80),archived:data.get('archived')==='on'};save();workordersPage();}
  if(form.id==='mirrorSearch'){stopPlayback();const query=String(data.get('query')||'').trim(),id=Object.keys(VIDEOS).find(id=>id.toLowerCase()===query.toLowerCase()),parsed=routeFromAddress(query);current().videoQuery=query.slice(0,120);save();const route=id?'#video/'+id:parsed?.startsWith('#video/')?parsed:'#video';if(location.hash===route)render();else location.hash=route;}
  if(form.id==='panLocate'){const input=String(data.get('share')||'').trim(),route=routeFromAddress(input);if(route?.startsWith('#pan/'))location.hash=route;else toast('请填写上传者给出的青禾网盘分享链接。');}
  if(form.id==='panExtract'){const r=unlockShare(getState(),'relay',data.get('password'));if(r.ok){save();pan('relay');}else result(r);}
  if(form.id==='complaintDraft'){current().complaintDraft=String(data.get('message')||'').slice(0,1000);save();result({ok:true,message:'建议草稿已保存在当前电脑，尚未发送。'});}
 });
 const pauseHidden=()=>{dwell.refresh();if(document.visibilityState!=='visible'&&playing){stopPlayback();updatePlayer(false);}};
 document.addEventListener('visibilitychange',pauseHidden);document.addEventListener('close',()=>dwell.refresh(),true);document.addEventListener('click',()=>queueMicrotask(()=>dwell.refresh()));window.addEventListener('focus',()=>dwell.refresh());window.addEventListener('blur',()=>{dwell.refresh();if(playing){stopPlayback();updatePlayer(false);}});
 function handleRoute(section,id){if(section==='portal'){portal(id||'home');return true;}if(section==='video'){id?videoPage(id):videoHome(current().videoQuery||'');return true;}if(section==='dynamic'){dynamic();return true;}if(section==='pan'){pan(id);return true;}return false;}
 return {handleRoute,suspend,reset:suspend};
}
